CREATE OR REPLACE FUNCTION public.start_fleet_mixed(p_player_id uuid,p_origin_planet_id uuid,p_destination_planet_id uuid,p_ships jsonb,p_mission_type text DEFAULT 'TRANSPORT') RETURNS TABLE(fleet_id uuid,ship_id text,quantity bigint,origin_planet_id uuid,destination_planet_id uuid,mission_type text,started_at timestamptz,arrives_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','pg_temp' AS $function$ DECLARE v_mission_type text:=upper(p_mission_type); v_fleet_id uuid; v_planet_player uuid; v_universe_id uuid; v_dest_galaxy int; v_dest_system int; v_dest_position int; v_origin_galaxy int; v_origin_system int; v_origin_position int; v_distance numeric; v_min_ship_speed numeric:=NULL; v_ship_speed numeric; v_fleet_speed numeric; v_evolution numeric; v_fleet_rate numeric; v_travel_time numeric; v_started_at timestamptz; v_arrives_at timestamptz; v_bonus numeric:=1; v_slots int; v_ship_id text; v_quantity bigint; v_available bigint; v_count int:=0; v_fuel numeric:=0; v_resources record; v_auth_user uuid; BEGIN v_auth_user:=auth.uid(); IF v_auth_user IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.players pl WHERE pl.id=p_player_id AND pl.user_id=v_auth_user) THEN RAISE EXCEPTION 'Player does not belong to authenticated user'; END IF; IF v_auth_user IS NULL AND NOT EXISTS(SELECT 1 FROM public.players pl WHERE pl.id=p_player_id AND coalesce(pl.is_guest,false)) THEN RAISE EXCEPTION 'Authentication required'; END IF; IF p_ships IS NULL OR jsonb_typeof(p_ships)<>'object' OR p_ships='{}'::jsonb THEN RAISE EXCEPTION 'Fleet composition must be a non-empty JSON object'; END IF; IF v_mission_type NOT IN ('ATTACK','TRANSPORT','DEPLOY','ESPIONAGE','RECYCLE','EXPEDITION') THEN RAISE EXCEPTION 'Invalid mission type: %',v_mission_type; END IF; SELECT p.player_id,p.universe_id,p.galaxy,p.system,p.position INTO v_planet_player,v_universe_id,v_origin_galaxy,v_origin_system,v_origin_position FROM public.planets p WHERE p.id=p_origin_planet_id AND NOT p.is_destroyed FOR UPDATE; IF NOT FOUND OR v_planet_player<>p_player_id THEN RAISE EXCEPTION 'Origin planet does not belong to player'; END IF; IF v_mission_type='EXPEDITION' THEN p_destination_planet_id:=NULL; v_dest_galaxy:=v_origin_galaxy; v_dest_system:=v_origin_system; v_dest_position:=16; v_slots:=public.get_player_expedition_slots(p_player_id); IF public.get_active_expedition_count(p_player_id)>=v_slots THEN RAISE EXCEPTION 'EXPEDITION_SLOTS_FULL: %/%',public.get_active_expedition_count(p_player_id),v_slots; END IF; ELSIF v_mission_type='RECYCLE' THEN SELECT df.galaxy,df.system,df.position INTO v_dest_galaxy,v_dest_system,v_dest_position FROM public.debris_fields df WHERE df.universe_id=v_universe_id AND (df.metal>0 OR df.crystal>0) ORDER BY abs(df.galaxy-v_origin_galaxy),abs(df.system-v_origin_system),abs(df.position-v_origin_position),df.id LIMIT 1 FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No debris field available for RECYCLE'; END IF; p_destination_planet_id:=NULL; ELSE IF p_destination_planet_id IS NULL THEN RAISE EXCEPTION 'Destination planet is required for %',v_mission_type; END IF; IF p_origin_planet_id=p_destination_planet_id THEN RAISE EXCEPTION 'Origin and destination planets must be different'; END IF; SELECT galaxy,system,position INTO v_dest_galaxy,v_dest_system,v_dest_position FROM public.planets WHERE id=p_destination_planet_id AND universe_id=v_universe_id AND NOT is_destroyed; IF NOT FOUND THEN RAISE EXCEPTION 'Destination planet not found, destroyed, or belongs to another universe'; END IF; END IF; FOR v_ship_id,v_quantity IN SELECT key,value::bigint FROM jsonb_each_text(p_ships) ORDER BY key LOOP v_count:=v_count+1; IF v_quantity<=0 THEN RAISE EXCEPTION 'Invalid quantity for %',v_ship_id; END IF; IF NOT EXISTS(SELECT 1 FROM public.ship_definitions WHERE id=v_ship_id) THEN RAISE EXCEPTION 'Unknown ship: %',v_ship_id; END IF; SELECT ps.quantity INTO v_available FROM public.planet_ships ps WHERE ps.planet_id=p_origin_planet_id AND ps.ship_id=v_ship_id FOR UPDATE; IF coalesce(v_available,0)<v_quantity THEN RAISE EXCEPTION 'Not enough %: available %, requested %',v_ship_id,coalesce(v_available,0),v_quantity; END IF; SELECT sd.speed INTO v_ship_speed FROM public.ship_definitions sd WHERE sd.id=v_ship_id; IF v_ship_speed IS NULL OR v_ship_speed<=0 THEN RAISE EXCEPTION 'Ship % cannot participate because its speed is %',v_ship_id,v_ship_speed; END IF; v_min_ship_speed:=CASE WHEN v_min_ship_speed IS NULL THEN v_ship_speed ELSE least(v_min_ship_speed,v_ship_speed) END; IF v_mission_type='RECYCLE' AND v_ship_id<>'recycler' THEN RAISE EXCEPTION 'RECYCLE mixed fleet may contain only recyclers'; END IF; END LOOP; IF v_count=0 THEN RAISE EXCEPTION 'Fleet composition contains no usable ships'; END IF; IF v_origin_galaxy<>v_dest_galaxy THEN v_distance:=20000*abs(v_origin_galaxy-v_dest_galaxy); ELSIF v_origin_system<>v_dest_system THEN v_distance:=2700+95*abs(v_origin_system-v_dest_system); ELSIF v_origin_position<>v_dest_position THEN v_distance:=1000+5*abs(v_origin_position-v_dest_position); ELSE v_distance:=5; END IF; FOR v_ship_id,v_quantity IN SELECT key,value::bigint FROM jsonb_each_text(p_ships) ORDER BY key LOOP v_fuel:=v_fuel+public.calculate_fleet_fuel_for_distance(v_distance,v_ship_id,v_quantity); END LOOP; PERFORM public.update_planet_resources_until(p_origin_planet_id,now()); SELECT * INTO v_resources FROM public.planet_resources pr WHERE pr.planet_id=p_origin_planet_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Planet resources not found'; END IF; IF v_resources.deuterium<v_fuel THEN RAISE EXCEPTION 'Insufficient deuterium for fleet fuel: required %, available %',v_fuel,v_resources.deuterium; END IF; SELECT fleet_speed INTO v_fleet_speed FROM public.universes WHERE id=v_universe_id; v_evolution:=public.calculate_universe_evolution_rate(v_universe_id); v_bonus:=1+(coalesce(public.get_active_expedition_item_effect(p_player_id,p_origin_planet_id,'fleet_speed_percent'),0)+coalesce(public.get_active_lifeform_research_effect(p_player_id,'fleet_speed_percent'),0))/100; v_fleet_rate:=v_fleet_speed*power(v_evolution,1.0/3.0)*v_bonus; IF v_mission_type='EXPEDITION' THEN v_travel_time:=((35000/100)*sqrt(v_distance*10/v_min_ship_speed)+10)/(coalesce((select expedition_speed from public.universes where id=v_universe_id),1)*power(v_evolution,1.0/3.0)*v_bonus); ELSE v_travel_time:=(v_distance/v_min_ship_speed)*3600/v_fleet_rate; END IF; v_travel_time:=greatest(v_travel_time,1); v_started_at:=now(); v_arrives_at:=v_started_at+(v_travel_time*interval '1 second'); UPDATE public.planet_resources SET deuterium=deuterium-v_fuel,updated_at=clock_timestamp() WHERE planet_id=p_origin_planet_id; FOR v_ship_id,v_quantity IN SELECT key,value::bigint FROM jsonb_each_text(p_ships) ORDER BY key LOOP UPDATE public.planet_ships SET quantity=quantity-v_quantity WHERE planet_id=p_origin_planet_id AND ship_id=v_ship_id; END LOOP; INSERT INTO public.fleet_movements(player_id,origin_planet_id,destination_planet_id,mission_type,started_at,arrives_at,status,destination_galaxy,destination_system,destination_position,expedition_hold_seconds,fuel_consumed) VALUES(p_player_id,p_origin_planet_id,p_destination_planet_id,v_mission_type,v_started_at,v_arrives_at,'OUTBOUND',v_dest_galaxy,v_dest_system,v_dest_position,3600,v_fuel) RETURNING id INTO v_fleet_id; INSERT INTO public.fleet_movement_ships(fleet_id,ship_id,quantity) SELECT v_fleet_id,key,value::bigint FROM jsonb_each_text(p_ships) ORDER BY key; RETURN QUERY SELECT v_fleet_id,fms.ship_id,fms.quantity,p_origin_planet_id,p_destination_planet_id,v_mission_type,v_started_at,v_arrives_at FROM public.fleet_movement_ships fms WHERE fms.fleet_id=v_fleet_id ORDER BY fms.ship_id; END; $function$; CREATE OR REPLACE FUNCTION public.start_colonize_fleet(p_player_id uuid,p_origin_planet_id uuid,p_galaxy int,p_system int,p_position int) RETURNS TABLE(fleet_id uuid,ship_id text,quantity bigint,origin_planet_id uuid,destination_planet_id uuid,mission_type text,started_at timestamptz,arrives_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','pg_temp' AS $function$ DECLARE v_origin record; v_available bigint; v_ship_speed numeric; v_fleet_speed numeric; v_evolution numeric; v_bonus numeric:=1; v_distance numeric; v_time numeric; v_fleet_rate numeric; v_fuel numeric; v_resources record; v_fleet_id uuid; v_started timestamptz; v_arrives timestamptz; v_auth_user uuid; BEGIN v_auth_user:=auth.uid(); IF v_auth_user IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.players pl WHERE pl.id=p_player_id AND pl.user_id=v_auth_user) THEN RAISE EXCEPTION 'Player does not belong to authenticated user'; END IF; IF v_auth_user IS NULL AND NOT EXISTS(SELECT 1 FROM public.players pl WHERE pl.id=p_player_id AND coalesce(pl.is_guest,false) ) THEN RAISE EXCEPTION 'Authentication required'; END IF; IF p_galaxy<1 OR p_system<1 OR p_position<1 OR p_position>15 THEN RAISE EXCEPTION 'Invalid colonization coordinate'; END IF; SELECT p.* INTO v_origin FROM public.planets p WHERE p.id=p_origin_planet_id AND NOT p.is_destroyed FOR UPDATE; IF NOT FOUND OR v_origin.player_id<>p_player_id THEN RAISE EXCEPTION 'Origin planet does not belong to player'; END IF; IF EXISTS(SELECT 1 FROM public.planets p WHERE p.universe_id=v_origin.universe_id AND p.galaxy=p_galaxy AND p.system=p_system AND p.position=p_position AND NOT p.is_destroyed) THEN RAISE EXCEPTION 'COLONIZE_TARGET_OCCUPIED'; END IF; SELECT ps.quantity INTO v_available FROM public.planet_ships ps WHERE ps.planet_id=p_origin_planet_id AND ps.ship_id='colony_ship' FOR UPDATE; IF coalesce(v_available,0)<1 THEN RAISE EXCEPTION 'Not enough colony_ship'; END IF; SELECT speed INTO v_ship_speed FROM public.ship_definitions WHERE id='colony_ship'; SELECT fleet_speed INTO v_fleet_speed FROM public.universes WHERE id=v_origin.universe_id; IF v_fleet_speed IS NULL OR v_fleet_speed<=0 THEN RAISE EXCEPTION 'Invalid universe fleet speed'; END IF; v_evolution:=public.calculate_universe_evolution_rate(v_origin.universe_id); v_fleet_rate:=v_fleet_speed*power(v_evolution,1.0/3.0); v_bonus:=1+(coalesce(public.get_active_expedition_item_effect(p_player_id,p_origin_planet_id,'fleet_speed_percent'),0)+coalesce(public.get_active_lifeform_research_effect(p_player_id,'fleet_speed_percent'),0))/100; v_distance:=CASE WHEN v_origin.galaxy<>p_galaxy THEN 20000*abs(v_origin.galaxy-p_galaxy) WHEN v_origin.system<>p_system THEN 2700+95*abs(v_origin.system-p_system) ELSE 1000+5*abs(v_origin.position-p_position) END; v_fuel:=public.calculate_fleet_fuel_for_distance(v_distance,'colony_ship',1); PERFORM public.update_planet_resources_until(p_origin_planet_id,now()); SELECT * INTO v_resources FROM public.planet_resources pr WHERE pr.planet_id=p_origin_planet_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Planet resources not found'; END IF; IF v_resources.deuterium<v_fuel THEN RAISE EXCEPTION 'Insufficient deuterium for colony ship fuel: required %, available %',v_fuel,v_resources.deuterium; END IF; v_time:=greatest((v_distance/v_ship_speed)*3600/(v_fleet_rate*v_bonus),1); v_started:=now(); v_arrives:=v_started+v_time*interval '1 second'; UPDATE public.planet_resources SET deuterium=deuterium-v_fuel,updated_at=clock_timestamp() WHERE planet_id=p_origin_planet_id; UPDATE public.planet_ships SET quantity=quantity-1 WHERE planet_id=p_origin_planet_id AND ship_id='colony_ship'; INSERT INTO public.fleet_movements(player_id,origin_planet_id,destination_planet_id,mission_type,started_at,arrives_at,status,destination_galaxy,destination_system,destination_position,expedition_hold_seconds,fuel_consumed) VALUES(p_player_id,p_origin_planet_id,NULL,'COLONIZE',v_started,v_arrives,'OUTBOUND',p_galaxy,p_system,p_position,3600,v_fuel) RETURNING id INTO v_fleet_id; INSERT INTO public.fleet_movement_ships(fleet_id,ship_id,quantity) VALUES(v_fleet_id,'colony_ship',1); RETURN QUERY SELECT v_fleet_id,'colony_ship'::text,1::bigint,p_origin_planet_id,NULL::uuid,'COLONIZE'::text,v_started,v_arrives; END; $function$;